-- Uldum: creature abilities
-- Most of the zone's creatures (the Neferset and Ramkahen's foes, Deathwing's minions, the Schnottz expedition and the desert
-- wildlife) had no AI or ran classic rows: port their abilities from the Cataclysm data, falling back to the classic data where
-- Cataclysm has none, keeping the quest scripts already in place; gossip and quest reward scripts of the references are left out.
-- The creatures no reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '45202,45204,45205,45765,45772,45799,45949,46126,46127,46128,46136,46646,46979,46993,47032,47067,47190,47202,47227,47283,47291,47292,47385,47567,47690,47699,47722,47726,47727,47729,47730,47738,47741,47742,47749,47753,47755,47760,47762,47801,47803,47810,47974,47978,47980,47981,47982,48040,48041,48043,48204,48205,48428,48443,48444,48514,48548,48625,48626,48627,48631,48668,48874,48883,49253,49528,50064,50154,50409,51217,51401,51402,51403,51404,51613,51671,51672,51673,51674,51753,51759,51760';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '47220';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
